<script>
  // We chose to use Buttons with aria-pressed due to Leonie Watson's recommendation
  // - https://lea0.verou.me/2022/07/button-group/
  // - https://tink.uk/perceived-affordances-and-the-functionality-mismatch/
  //
  import { checkForAccessibleName, init } from '../../utils'

  let {
    items = $bindable([]),
    selected = $bindable(null),
    class: klass = '',
    direction = 'horizontal',
    ...rest
  } = $props()

  // Accessible name warning
  init(() => checkForAccessibleName('Button Group', rest))

  // Create divider class if direction is provided.
  const dividerClass = $derived(
    klass.includes('card-divided-')
      ? ''
      : direction === 'horizontal'
        ? 'card-divided-horizontal'
        : direction === 'vertical'
          ? 'card-divided-vertical'
          : '',
  )

  // Normalize items
  const normalizedItems = $derived.by(() => {
    const mapped = items.map(item => {
      if (typeof item === 'string') {
        return { value: item, pressed: false, onclick: handleClick }
      }

      const { selected, onclick, ...rest } = item
      return {
        onclick: handleClick,
        ...rest,
        pressed: selected ?? false,
        userClickEvent: onclick,
      }
    })

    if (!mapped.some(item => item.pressed)) mapped[0].pressed = true
    return mapped
  })

  function handleClick(event) {
    const index = parseInt(event.target.getAttribute('index'))
    selected = items[index]
    items = items.map((item, i) => {
      item.selected = i === index
      return item
    })
    const userClickEvt = normalizedItems[index].userClickEvent
    if (userClickEvt) userClickEvt(event)
  }
</script>

<div
  {...rest}
  class="button-group card-divided {klass} {dividerClass}"
  role="group"
>
  {#each normalizedItems as item, index (item.value)}
    {@const { value, pressed, onclick, ...r } = item}
    <button {...r} aria-pressed={pressed} {index} {onclick}>
      {value}
    </button>
  {/each}
</div>
